mapper.select:
SELECT tenant_id, handle, instance_id, instance_revision, installation_revision, capability_id, version_id, timeout,
       workflow_key, definition_json, config_json, bindings_json, resolved_bindings_json, custom_prompt, descriptor,
       digest FROM public.nw_runtime_workflow_bindings
WHERE tenant_id=current_setting('app.tenant_id',true) AND handle=#{target.handle.value}
  AND instance_id=#{target.instanceId} AND instance_revision=#{target.instanceRevision}
  AND installation_revision=#{target.installationRevision}
  AND capability_id=#{target.capability.capabilityId} AND version_id=#{target.capability.versionId}
